onErrorMessage&quot;:null,&quot;Metadata&quot;:{},&quot;Id&quot;:0,&quot;Description&quot;:null,&quot;ActionType&quot;:&quot;RedirectToUrl&quot;,&quot;OrderIndex&quot;:1,&quot;Condition&quot;:null,&quot;Parameters&quot;:{&quot;Url&quot;:&quot;[ExcelURL]&quot;,&quot;EscapeUrl&quot;:&quot;&quot;,&quot;OpenInPopup&quot;:&quot;&quot;,&quot;PopupTitle&quot;:&quot;&quot;,&quot;OpenInNewTab&quot;:&quot;&quot;,&quot;ForceDownload&quot;:true},&quot;IsDeleted&quot;:false},&quot;EventName&quot;:&quot;BulkAction&quot;,&quot;IsDeleted&quot;:false}],&quot;BulkActionsAfter&quot;:[],&quot;ItemActions&quot;:[],&quot;Url&quot;:&quot;&amp;amp;buttonName=ExportCalculLichidare&quot;,&quot;ModuleId&quot;:927,&quot;AutoName&quot;:true,&quot;Name&quot;:&quot;ExportCalculLichidare&quot;,&quot;Title&quot;:&quot;Export Calcul Lichidare&quot;,&quot;Help&quot;:null,&quot;ShowCondition&quot;:&quot;([HasRole:Admins] || [HasRole:CitizenDevelopers] || [HasRole:Low-CodeEngineer] || [HasRole:Managers] || [HasRole:Payroll_Operator] || [HasRole:Users])&quot;,&quot;IsEnabled&quot;:false,&quot;Metadata&quot;:{},&quot;Type&quot;:&quot;GridButton&quot;,&quot;OrderIndex&quot;:0,&quot;CssClass&quot;:&quot;link&quot;,&quot;CustomCssClass&quot;:null,&quot;IconClass&quot;:null,&quot;FaIconClass&quot;:null,&quot;PermissionAllUsers&quot;:false,&quot;PermissionsExportJson&quot;:&quot;[\&quot;Managers\&quot;,\&quot;Admins\&quot;,\&quot;Citizen Developers\&quot;,\&quot;Low-Code Engineer\&quot;,\&quot;Payroll_Operator\&quot;,\&quot;Users\&quot;]&quot;,&quot;Permissions&quot;:[8,6,7,5,13,9],&quot;AskForConfirmation&quot;:false,&quot;ConfirmationMessage&quot;:&quot;Are you sure you want to do this?&quot;,&quot;ConfirmationOk&quot;:&quot;Yes, pretty sure&quot;,&quot;ConfirmationCancel&quot;:&quot;No, I&#39;m having second thoughts&quot;,&quot;JsCode&quot;:null,&quot;IsClientButton&quot;:false,&quot;ButtonGroupId&quot;:null,&quot;ButtonGroupName&quot;:null,&quot;Id&quot;:0,&quot;EnableCondition&quot;:null,&quot;IsDeleted&quot;:false},{&quot;EnableSelection&quot;:false,&quot;RequiresSelection&quot;:false,&quot;RequiresData&quot;:false,&quot;ShowCount&quot;:false,&quot;SumColumn&quot;:null,&quot;SumMode&quot;:&quot;Default&quot;,&quot;SumCoefficient&quot;:null,&quot;TextBeforeSum&quot;:null,&quot;TextAfterSum&quot;:null,&quot;ConfirmationPosition&quot;:&quot;centered&quot;,&quot;VerticalPosition&quot;:&quot;Top&quot;,&quot;HorizontalPosition&quot;:&quot;Right&quot;,&quot;BulkActions&quot;:[{&quot;Id&quot;:0,&quot;ButtonId&quot;:0,&quot;ActionInfo&quot;:{&quot;ActionErrorMessage&quot;:null,&quot;Metadata&quot;:{},&quot;Id&quot;:0,&quot;Description&quot;:&quot;Calcul Lichidare&quot;,&quot;ActionType&quot;:&quot;RunSql&quot;,&quot;OrderIndex&quot;:0,&quot;Condition&quot;:&quot;&quot;,&quot;Parameters&quot;:{&quot;DbConnector&quot;:{&quot;Type&quot;:&quot;Database&quot;,&quot;Group&quot;:&quot;&quot;,&quot;EntireGroup&quot;:false},&quot;ConnectionString&quot;:&quot;&quot;,&quot;QueryTimeout&quot;:&quot;&quot;,&quot;SqlQuery&quot;:&quot;/*=====================================================
    0️⃣ Declarare Statusuri
=====================================================*/
DECLARE @StatusDraft INT
DECLARE @StatusBlocat INT

SELECT @StatusDraft = Id 
FROM app.StatusCalcul 
WHERE Denumire = &#39;Draft&#39;

SELECT @StatusBlocat = Id 
FROM app.StatusCalcul 
WHERE Denumire = &#39;Blocat&#39;


/*=====================================================
    1️⃣ Creează ControlLichidare dacă nu există
=====================================================*/
IF NOT EXISTS (
    SELECT 1
    FROM app.ControlLichidare
    WHERE Anul = @Anul
      AND Luna = @Luna
      AND CodSucursala = @CodSucursala
)
BEGIN
    INSERT INTO app.ControlLichidare
    (
        Anul,
        Luna,
        CodSucursala,
        Status,
        CreatDe,
        DataCreare
    )
    VALUES
    (
        @Anul,
        @Luna,
        @CodSucursala,
        @StatusDraft,
        @UserName,
        GETDATE()
    )
END


/*=====================================================
    2️⃣ Oprește dacă luna este Blocată (corect)
=====================================================*/
DECLARE @StatusCurent INT

SELECT @StatusCurent = Status
FROM app.ControlLichidare
WHERE 
    Anul = @Anul
    AND Luna = @Luna
    AND CodSucursala = @CodSucursala

IF @StatusCurent IS NULL 
BEGIN
    RAISERROR (&#39;Nu exista ControlLichidare pentru aceasta selectie.&#39;,16,1)
    RETURN
END


IF @StatusCurent = @StatusBlocat
BEGIN
    RAISERROR (&#39;Luna este blocata. Deblocati pentru recalcul.&#39;,16,1)
    RETURN
END

/*=====================================================
    3️⃣ Ștergere calcul existent
=====================================================*/
DELETE FROM app.CalculLichidare
WHERE Anul = @Anul
  AND Luna = @Luna
  AND CodSucursala = @CodSucursala


/*=====================================================
    4️⃣ Motor calcul
=====================================================*/

;WITH Parametri AS 

    ( SELECT [Initializari:ZileLucratoare_old(Anul = [GetOrSession:YearV],Luna = [GetOrSession:MonthV])] AS ZileLucratoare )


INSERT INTO app.CalculLichidare
(
    IdSalariat,
    CodSucursala,
    Marca,
    TipNorma,
    ZileLucratoare,
    ZileCO,
    ZileCM,
    ZileLucrate,
    OreLucrate,
    SalariuBrut,
    SalBrutEfectiv,
    TicheteMasa,
    Agenti,
    Remiza,
    AlteDrepturi,
    BrutContributiv,
    TotalBrut,
    CAS,
    CASS,
    CAM,
    BazaImpozabila,
    ImpozitVenit,
    CAR,
    PensiiAlimentare,
    PensiiFacultative,

    Chirii,
    Casa,
    Banca,
    Garantii,
    Popriri,
    Imputatii,
    AlteRate,

    TotalRetineri,
    VenitNet,
    SalariuNet,
    NetDePlata,
    Anul,
    Luna,
    DataCalcul,
    Status
)

SELECT
    a.Id,
    @CodSucursala,
    a.Marca,
    a.TipNorma,

    p.ZileLucratoare,
    ISNULL(co.ZileCOLuna,0),
    ISNULL(cm.ZileCMLuna,0),
    zl.ZileLucrate,

    ca.OreLucrate,
    b.Salariu,
    ca.SalBrutEfectiv,
    ca.TicheteTotale,
    ISNULL(ag.SumaAgent,0),
    ISNULL(rem.Sume_Remiza,0),
    0,
    ca.BrutContributiv,
    ca.TotalBrut,
    ca.CAS,
    ca.CASS,
    0,
    ca.BazaImpozabila,
    ca.ImpozitVenit,
    0, --CAR
    ISNULL(pa.PensiiAlimentare,0),
    0, --Pensie Facultativa
    ISNULL(ret.Chirii,0),
    ISNULL(ret.Casa,0), 
    ISNULL(ret.Banca,0),
    0, --Garantii (daca nu ai inca)
    ISNULL(ret.Popriri,0),
    ISNULL(ret.Imputatii,0),
    ISNULL(ret.AlteRate,0),
    ISNULL(tr.TotalRetineri,0), 

ca.VenitNet,
ca.SalariuNet,
   CASE 
   WHEN ca.SalariuNet - tr.TotalRetineri &amp;lt; 0
   THEN 0
   ELSE ca.SalariuNet - tr.TotalRetineri
END,

    @Anul,
    @Luna,
    GETDATE(),
    @StatusDraft

FROM app.Salariat a
LEFT JOIN app.NomGrilaSalarizare b
       ON b.Clasa = a.Clasa
      AND b.TipMediu = &#39;U&#39;

LEFT JOIN app.TSTichetMasa t
       ON t.Anul = @Anul
      AND t.Luna = @Luna

CROSS JOIN Parametri p

OUTER APPLY (
    SELECT
        SUM(
              CASE WHEN MONTH(c.Interval1DatadeInceput)=@Luna
               AND YEAR(c.Interval1DatadeInceput)=@Anul
              THEN ISNULL(c.NrZileCO1,0) ELSE 0 END
            + CASE WHEN MONTH(c.Interval2DatadeInceput)=@Luna
               AND YEAR(c.Interval2DatadeInceput)=@Anul
              THEN ISNULL(c.NrZileCO2,0) ELSE 0 END
            + CASE WHEN MONTH(c.Interval3DatadeInceput)=@Luna
               AND YEAR(c.Interval3DatadeInceput)=@Anul
              THEN ISNULL(c.NrZileCO3,0) ELSE 0 END
        ) AS ZileCOLuna
    FROM app.ConcediudeOdihna c
    WHERE c.Marca = a.Marca
      AND c.CodSucursala = @CodSucursala
) co

OUTER APPLY (
    SELECT SUM(m.TotZileLucratoare) AS ZileCMLuna
    FROM app.ConcediuMedical m
    WHERE m.Marca = a.Marca
      AND m.CodSucursala = @CodSucursala
      AND m.AnulDePlata = @Anul
      AND m.LunaDePlata = @Luna
) cm

CROSS APPLY (
    SELECT
        CASE
            WHEN p.ZileLucratoare
                 - ISNULL(co.ZileCOLuna,0)
                 - ISNULL(cm.ZileCMLuna,0) &amp;lt; 0
            THEN 0
            ELSE p.ZileLucratoare
                 - ISNULL(co.ZileCOLuna,0)
                 - ISNULL(cm.ZileCMLuna,0)
        END AS ZileLucrate
) zl

OUTER APPLY (
    SELECT SUM(ISNULL(ca2.Suma,0)) AS SumaAgent
    FROM app.CalculAgent ca2
    WHERE ca2.Marca = a.Marca
      AND ca2.Anul = @Anul
      AND ca2.Luna = @Luna
      AND ca2.CodSucursala = @CodSucursala
) ag

OUTER APPLY (
    SELECT SUM(ISNULL(x.Suma,0)) AS Sume_Remiza
    FROM app.Remiza x
    WHERE x.Marca = a.Marca
      AND x.Anul = @Anul
      AND x.Luna = @Luna
      AND x.CodSucursala = @CodSucursala
) rem
OUTER APPLY (
    SELECT 
        SUM(
              ISNULL(p.Rata,0)
            + ISNULL(p.Rest,0)
            + ISNULL(p.Taxa,0)
            + ISNULL(p.Taxam,0)
        ) AS PensiiAlimentare
    FROM app.PensieAlimentara p
    WHERE p.Marca = a.Marca
      AND p.Anul = @Anul
      AND p.Luna = @Luna
      AND p.CodSucursala = @CodSucursala
) pa

OUTER APPLY (
    SELECT 
        SUM(CASE WHEN r.TipRata = 1 
            THEN ISNULL(r.Rata,0) + ISNULL(r.Dobanda,0) + ISNULL(r.RestDePlata,0) 
            ELSE 0 END) AS Chirii,
        SUM(CASE WHEN r.TipRata = 2 
            THEN ISNULL(r.Rata,0) + ISNULL(r.Dobanda,0) + ISNULL(r.RestDePlata,0) 
            ELSE 0 END) AS Casa,
       SUM(CASE WHEN r.TipRata = 3 
            THEN ISNULL(r.Rata,0) + ISNULL(r.Dobanda,0) + ISNULL(r.RestDePlata,0) 
            ELSE 0 END) AS Banca,

        SUM(CASE WHEN r.TipRata = 4 
            THEN ISNULL(r.Rata,0) + ISNULL(r.Dobanda,0) + ISNULL(r.RestDePlata,0) 
            ELSE 0 END) AS Imputatii,

        SUM(CASE WHEN r.TipRata = 6 
            THEN ISNULL(r.Rata,0) + ISNULL(r.Dobanda,0) + ISNULL(r.RestDePlata,0) 
            ELSE 0 END) AS Popriri,

        SUM(CASE WHEN r.TipRata = 7 
            THEN ISNULL(r.Rata,0) + ISNULL(r.Dobanda,0) + ISNULL(r.RestDePlata,0) 
            ELSE 0 END) AS AlteRate

    FROM app.Retinere r
    WHERE r.Marca = a.Marca
      AND r.Anul = @Anul
      AND r.Luna = @Luna
      AND r.CodSucursala = @CodSucursala
) ret

CROSS APPLY (
    SELECT 
        (
            ISNULL(ret.Chirii,0)
          + ISNULL(ret.Casa,0)
          + ISNULL(ret.Banca,0)
          + ISNULL(ret.Popriri,0)
          + ISNULL(ret.Imputatii,0)
          + ISNULL(ret.AlteRate,0)
          + ISNULL(pa.PensiiAlimentare,0)
        ) AS TotalRetineri
) tr
CROSS APPLY (
    SELECT
        zl.ZileLucrate * a.TipNorma * 8 AS OreLucrate,
        ROUND((b.Salariu / (p.ZileLucratoare * 8)) * (zl.ZileLucrate * a.TipNorma * 8),0) AS SalBrutEfectiv,
        ISNULL(t.Valoare,0) * zl.ZileLucrate AS TicheteTotale,
        (
            ROUND((b.Salariu / (p.ZileLucratoare * 8)) * (zl.ZileLucrate * a.TipNorma * 8),0)
            + ISNULL(ag.SumaAgent,0)
            + ISNULL(rem.Sume_Remiza,0)
        ) AS BrutContributiv,
        (
            ROUND((b.Salariu / (p.ZileLucratoare * 8)) * (zl.ZileLucrate * a.TipNorma * 8),0)
            + ISNULL(ag.SumaAgent,0)
            + ISNULL(rem.Sume_Remiza,0)
            + (ISNULL(t.Valoare,0) * zl.ZileLucrate)
        ) AS TotalBrut,
        ROUND((
            ROUND((b.Salariu / (p.ZileLucratoare * 8)) * (zl.ZileLucrate * a.TipNorma * 8),0)
            + ISNULL(ag.SumaAgent,0)
            + ISNULL(rem.Sume_Remiza,0)
        ) * 0.25,0) AS CAS,
        ROUND((
            ROUND((b.Salariu / (p.ZileLucratoare * 8)) * (zl.ZileLucrate * a.TipNorma * 8),0)
            + ISNULL(ag.SumaAgent,0)
            + ISNULL(rem.Sume_Remiza,0)
            + (ISNULL(t.Valoare,0) * zl.ZileLucrate)
        ) * 0.10,0) AS CASS,
        (
            (
                ROUND((b.Salariu / (p.ZileLucratoare * 8)) * (zl.ZileLucrate * a.TipNorma * 8),0)
                + ISNULL(ag.SumaAgent,0)
                + ISNULL(rem.Sume_Remiza,0)
            ) * 0.65
        ) AS BazaImpozabila,
        ROUND((
            (
                ROUND((b.Salariu / (p.ZileLucratoare * 8)) * (zl.ZileLucrate * a.TipNorma * 8),0)
                + ISNULL(ag.SumaAgent,0)
                + ISNULL(rem.Sume_Remiza,0)
            ) * 0.65
        ) * 0.10,0) AS ImpozitVenit,
        (
            (
                ROUND((b.Salariu / (p.ZileLucratoare * 8)) * (zl.ZileLucrate * a.TipNorma * 8),0)
                + ISNULL(ag.SumaAgent,0)
                + ISNULL(rem.Sume_Remiza,0)
            ) * 0.65
        ) * 0.90 AS SalariuNet,
        (
            (
                ROUND((b.Salariu / (p.ZileLucratoare * 8)) * (zl.ZileLucrate * a.TipNorma * 8),0)
                + ISNULL(ag.SumaAgent,0)
                + ISNULL(rem.Sume_Remiza,0)
            ) * 0.65
        ) * 0.90 AS VenitNet
) ca

WHERE 
a.CodSucursala = @CodSucursala
AND a.Anul = @Anul
AND a.Luna = @Luna


/*=====================================================
    5️⃣ Validare: dacă nu s-a inserat nimic → eroare
=====================================================*/
IF NOT EXISTS (
    SELECT 1
    FROM app.CalculLichidare
    WHERE Anul = @Anul
      AND Luna = @Luna
      AND CodSucursala = @CodSucursala
)
BEGIN
    RAISERROR (&#39;Nu s-au generat inregistrari pentru aceasta luna.&#39;,16,1)
    RETURN
END
;
/*=====================================================
    6️⃣ Update ControlLichidare (status + audit)
=====================================================*/

DECLARE @StatusConfirmat INT

SELECT @StatusConfirmat = Id 
FROM app.StatusCalcul 
WHERE Denumire = &#39;Confirmat&#39;


UPDATE CLControl
SET 
    Status = 
        CASE 
            WHEN EXISTS (
                SELECT 1
                FROM app.CalculLichidare CL
                WHERE 
                    CL.Anul = CLControl.Anul
                    AND CL.Luna = CLControl.Luna
                    AND CL.CodSucursala = CLControl.CodSucursala
                    AND CL.Status &amp;lt;&amp;gt; @StatusConfirmat
            )
            THEN @StatusDraft
            ELSE @StatusConfirmat
        END,

    ModificatDe = @UserName,
    DataModificarii = GETDATE()

FROM app.ControlLichidare CLControl
WHERE 
    CLControl.Anul = @Anul
    AND CLControl.Luna = @Luna
    AND CLControl.CodSucursala = @CodSucursala
    AND CLControl.Status &amp;lt;&amp;gt; @StatusBlocat&quot;,&quot;BindTokens&quot;:[{&quot;value&quot;:&quot;[GetOrSession:BranchV]&quot;,&quot;name&quot;:&quot;CodSucursala&quot;},{&quot;value&quot;:&quot;[GetOrSession:YearV]&quot;,&quot;name&quot;:&quot;Anul&quot;},{&quot;value&quot;:&quot;[GetOrSession:MonthV]&quot;,&quot;name&quot;:&quot;Luna&quot;},{&quot;value&quot;:&quot;[User:UserName]&quot;,&quot;name&quot;:&quot;Username&quot;}],&quot;OutputTokenName&quot;:&quot;&quot;,&quot;ExtractColumns&quot;:&quot;&quot;,&quot;OnError&quot;:[],&quot;ShowErrors&quot;:false},&quot;IsDeleted&quot;:false},&quot;EventName&quot;:&quot;BulkAction&quot;,&quot;IsDeleted&quot;:false},{&quot;Id&quot;:0,&quot;ButtonId&quot;:0,&quot;ActionInfo&quot;:{&quot;ActionErrorMessage&quot;:null,&quot;Metadata&quot;:{},&quot;Id&quot;:0,&quot;Description&quot;:null,&quot;ActionType&quot;:&quot;RefreshGrid&quot;,&quot;OrderIndex&quot;:1,&quot;Condition&quot;:null,&quot;Parameters&quot;:{&quot;ModuleId&quot;:{&quot;Expression&quot;:&quot;&quot;,&quot;Value&quot;:&quot;d64048dd-65dd-454f-a4de-b1727271f85f&quot;,&quot;IsExpression&quot;:false,&quot;Parameters&quot;:{}}},&quot;IsDeleted&quot;:false},&quot;EventName&quot;:&quot;BulkAction&quot;,&quot;IsDeleted&quot;:false},{&quot;Id&quot;:0,&quot;ButtonId&quot;:0,&quot;ActionInfo&quot;:{&quot;ActionErrorMessage&quot;:null,&quot;Metadata&quot;:{},&quot;Id&quot;:0,&quot;Description&quot;:null,&quot;ActionType&quot;:&quot;ShowToast&quot;,&quot;OrderIndex&quot;:2,&quot;Condition&quot;:&quot;[Helper:TokenStatusCalculTaxePostale] == 1&quot;,&quot;Parameters&quot;:{&quot;Heading&quot;:&quot;&quot;,&quot;Message&quot;:&quot;&amp;lt;p&amp;gt;Aveti Calcul Taxe Pensii Alimentare neconfirmat!&amp;lt;/p&amp;gt;&quot;,&quot;Icon&quot;:{&quot;Expression&quot;:&quot;&quot;,&quot;Value&quot;:&quot;default&quot;,&quot;IsExpression&quot;:false,&quot;Parameters&quot;:{}},&quot;BgColor&quot;:&quot;&quot;,&quot;Transition&quot;:{&quot;Expression&quot;:&quot;&quot;,&qu