firmationCancel&quot;:&quot;No, I&#39;m having second thoughts&quot;,&quot;JsCode&quot;:null,&quot;IsClientButton&quot;:false,&quot;ButtonGroupId&quot;:null,&quot;ButtonGroupName&quot;:null,&quot;Id&quot;:0,&quot;EnableCondition&quot;:&quot;[Helper:TokenStatusCalculLichidare] == 1 &amp;amp;&amp;amp; [Helper:TokenStatusCalculTaxePostale] == 2&quot;,&quot;IsDeleted&quot;:false},{&quot;EnableSelection&quot;:false,&quot;RequiresSelection&quot;:false,&quot;RequiresData&quot;:false,&quot;ShowCount&quot;:false,&quot;SumColumn&quot;:null,&quot;SumMode&quot;:&quot;Default&quot;,&quot;SumCoefficient&quot;:null,&quot;TextBeforeSum&quot;:null,&quot;TextAfterSum&quot;:null,&quot;ConfirmationPosition&quot;:&quot;centered&quot;,&quot;VerticalPosition&quot;:&quot;Top&quot;,&quot;HorizontalPosition&quot;:&quot;Right&quot;,&quot;BulkActions&quot;:[{&quot;Id&quot;:0,&quot;ButtonId&quot;:0,&quot;ActionInfo&quot;:{&quot;ActionErrorMessage&quot;:null,&quot;Metadata&quot;:{},&quot;Id&quot;:0,&quot;Description&quot;:&quot;Exceptii Prezenta&quot;,&quot;ActionType&quot;:&quot;ExecuteActions&quot;,&quot;OrderIndex&quot;:0,&quot;Condition&quot;:&quot;&quot;,&quot;Parameters&quot;:{&quot;ActionList&quot;:[{&quot;Title&quot;:&quot;Run SQL Query&quot;,&quot;ActionType&quot;:&quot;RunSql&quot;,&quot;Description&quot;:&quot;Calcul Numar Exceptii (doar pentru TipExceptie=\&quot;DEPASIRE_ZILE\&quot;)&quot;,&quot;Condition&quot;:&quot;&quot;,&quot;Parameters&quot;:{&quot;DbConnector&quot;:{&quot;Type&quot;:&quot;Database&quot;,&quot;Group&quot;:&quot;&quot;,&quot;EntireGroup&quot;:false},&quot;ConnectionString&quot;:&quot;&quot;,&quot;QueryTimeout&quot;:&quot;&quot;,&quot;SqlQuery&quot;:&quot;;WITH Parametri AS (
    SELECT
        [Initializari:ZileLucratoare_old(Anul = [GetOrSession:YearV],Luna = [GetOrSession:MonthV])] AS ZileLucratoare
)

SELECT COUNT(*) AS NrExceptii
FROM (
    SELECT a.Id
    FROM app.Salariat a
CROSS JOIN Parametri p
    OUTER APPLY (
    SELECT
        SUM(
            CASE
                WHEN c.Interval1DatadeInceput IS NOT NULL
                 AND MONTH(c.Interval1DatadeInceput) = @Luna
                 AND YEAR (c.Interval1DatadeInceput) = @Anul
                THEN ISNULL(c.NrZileCO1, 0)
                ELSE 0
            END
          + CASE
                WHEN c.Interval2DatadeInceput IS NOT NULL
                 AND MONTH(c.Interval2DatadeInceput) = @Luna
                 AND YEAR (c.Interval2DatadeInceput) = @Anul
                THEN ISNULL(c.NrZileCO2, 0)
                ELSE 0
            END
          + CASE
                WHEN c.Interval3DatadeInceput IS NOT NULL
                 AND MONTH(c.Interval3DatadeInceput) = @Luna
                 AND YEAR (c.Interval3DatadeInceput) = @Anul
                THEN ISNULL(c.NrZileCO3, 0)
                ELSE 0
            END
        ) AS ZileCOLuna
    FROM app.ConcediudeOdihna c
    WHERE c.Marca        = a.Marca
      AND c.CodSucursala = @CodSucursala
) co

    OUTER APPLY (
        SELECT
            SUM(m.TotZileLucratoare) AS ZileCMLuna
        FROM app.ConcediuMedical m
        WHERE m.Marca = a.Marca
          AND m.CodSucursala = @CodSucursala
          AND m.AnulDePlata = @Anul
          AND m.LunaDePlata = @Luna
    ) cm

    WHERE
        a.Anul = @Anul
        AND a.Luna = @Luna
        AND a.CodSucursala = @CodSucursala
        AND (
            p.ZileLucratoare
            - ISNULL(co.ZileCOLuna,0)
            - ISNULL(cm.ZileCMLuna,0)
        ) &amp;lt; 0
