DECLARE @IdConfirmat INT
DECLARE @IdDraft INT
DECLARE @StatusBlocat INT

SELECT @IdConfirmat = Id FROM app.StatusCalcul WHERE Denumire = &#39;Confirmat&#39;
SELECT @IdDraft     = Id FROM app.StatusCalcul WHERE Denumire = &#39;Draft&#39;
SELECT @StatusBlocat = Id FROM app.StatusCalcul WHERE Denumire = &#39;Blocat&#39;


/*=====================================================
    1️⃣ Confirmare CalculLichidare
=====================================================*/
UPDATE app.CalculLichidare
SET 
    Status = @IdConfirmat,
    LastModifiedDate = SYSDATETIMEOFFSET(),
    LastModifiedBy = @UserId
WHERE 
    CodSucursala = @CodSucursala
    AND Anul = @Anul
    AND Luna = @Luna
    AND ISNULL(Status, @IdDraft) &amp;lt;&amp;gt; @IdConfirmat;


/*=====================================================
    3️⃣ Update ControlLichidare (status + audit)
=====================================================*/
UPDATE CLControl
SET 
    Status = 
        CASE 
            WHEN EXISTS (
                SELECT 1
                FROM app.CalculLichidare CL
                WHERE 
                    CL.Anul = CLControl.Anul
                    AND CL.Luna = CLControl.Luna
                    AND CL.CodSucursala = CLControl.CodSucursala
                    AND CL.Status &amp;lt;&amp;gt; @IdConfirmat
            )
            THEN @IdDraft
            ELSE @IdConfirmat
        END,

    ModificatDe = @Username,
    DataModificarii = GETDATE()

FROM app.ControlLichidare CLControl
WHERE 
    CLControl.Anul = @Anul
    AND CLControl.Luna = @Luna
    AND CLControl.CodSucursala = @CodSucursala
    AND CLControl.Status &amp;lt;&amp;gt; @StatusBlocat;&quot;,&quot;BindTokens&quot;:[{&quot;value&quot;:&quot;[GetOrSession:BranchV]&quot;,&quot;name&quot;:&quot;CodSucursala&quot;},{&quot;value&quot;:&quot;[GetOrSession:YearV]&quot;,&quot;name&quot;:&quot;Anul&quot;},{&quot;value&quot;:&quot;[GetOrSession:MonthV]&quot;,&quot;name&quot;:&quot;Luna&quot;},{&quot;value&quot;:&quot;[User:UserId]&quot;,&quot;name&quot;:&quot;UserId&quot;},{&quot;value&quot;:&quot;[User:UserName]&quot;,&quot;name&quot;:&quot;UserName&quot;}],&quot;OutputTokenName&quot;:&quot;&quot;,&quot;ExtractColumns&quot;:&quot;&quot;,&quot;OnError&quot;:[],&quot;ShowErrors&quot;:false},&quot;IsDeleted&quot;:false},&quot;EventName&quot;:&quot;BulkAction&quot;,&quot;IsDeleted&quot;:false},{&quot;Id&quot;:0,&quot;ButtonId&quot;:0,&quot;ActionInfo&quot;:{&quot;ActionErrorMessage&quot;:null,&quot;Metadata&quot;:{},&quot;Id&quot;:0,&quot;Description&quot;:&quot;Calcul Lichidare confirmat cu succes&quot;,&quot;ActionType&quot;:&quot;ShowToastAndContinue&quot;,&quot;OrderIndex&quot;:2,&quot;Condition&quot;:null,&quot;Parameters&quot;:{&quot;Heading&quot;:&quot;&quot;,&quot;Message&quot;:&quot;&amp;lt;p&amp;gt;Calcul Lichidare confirmat cu succes.&amp;lt;/p&amp;gt;&quot;,&quot;Icon&quot;:{&quot;Expression&quot;:&quot;&quot;,&quot;Value&quot;:&quot;default&quot;,&quot;IsExpression&quot;:false,&quot;Parameters&quot;:{}},&quot;BgColor&quot;:&quot;&quot;,&quot;Transition&quot;:{&quot;Expression&quot;:&quot;&quot;,&quot;Value&quot;:&quot;fade&quot;,&quot;IsExpression&quot;:false,&quot;Parameters&quot;:{}},&quot;AllowToastClose&quot;:&quot;&quot;,&quot;CallBackJsCode&quot;:&quot;&quot;,&quot;HideTime&quot;:&quot;1000&quot;,&quot;Stack&quot;:&quot;1&quot;,&quot;ToastPosition&quot;:{&quot;Expression&quot;:&quot;&quot;,&quot;Value&quot;:&quot;bottom-center&quot;,&quot;IsExpression&quot;:false,&quot;Parameters&quot;:{}},&quot;TextAlignment&quot;:{&quot;Expression&quot;:&quot;&quot;,&quot;Value&quot;:&quot;left&quot;,