SELECT @IdDraft = Id FROM app.StatusCalcul WHERE Denumire = &#39;Draft&#39;
SELECT @StatusBlocat = Id FROM app.StatusCalcul WHERE Denumire = &#39;Blocat&#39;


/*=====================================================
    1️⃣ Verificare blocare
=====================================================*/
IF EXISTS (
    SELECT 1
    FROM app.ControlLichidare
    WHERE 
        Anul = @Anul
        AND Luna = @Luna
        AND CodSucursala = @CodSucursala
        AND Status = @StatusBlocat
)
BEGIN
    RAISERROR (&#39;Luna este blocata. Deblocati pentru redeschidere.&#39;,16,1)
    RETURN
END


/*=====================================================
    2️⃣ Redeschidere CalculLichidare
=====================================================*/
UPDATE app.CalculLichidare
SET 
    Status = @IdDraft,
    LastModifiedDate = SYSDATETIMEOFFSET(),
    LastModifiedBy = @UserId
WHERE 
    CodSucursala = @CodSucursala
    AND Anul = @Anul
    AND Luna = @Luna;


